INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Teamarbeit in IT-Projekten immer online sein muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch offline möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend online"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Tool für die Zusammenarbeit im IT-Team wähle?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Höchste Kosten", "correct": false, "because": "Budget ist relevant"}, {"text": "Buntes Design", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools fördern die Zusammenarbeit in IT-Projekten?', 5, '[{"text": "Versionskontrolle", "correct": true, "because": "Sichert Code-Management"}, {"text": "Kommunikationsplattform", "correct": true, "because": "Ermöglicht Austausch"}, {"text": "Hochpreisige Hardware", "correct": false, "because": "Kein Kollaborationstool"}, {"text": "Grafiksoftware", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gemeinsame Tools verbessern die Effizienz. b) Jeder muss dieselbe Software nutzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ist möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein IT-Projektteam organisiere?', 4, '[{"text": "Kommunikationswege", "correct": false, "because": "Schlüssel für Zusammenarbeit"}, {"text": "Rollenverteilung", "correct": false, "because": "Definiert Aufgaben"}, {"text": "Büroausstattung", "correct": true, "because": "Sekundär für Kollaboration"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Versionskontrolle für die Teamarbeit zwingend ist?', 2, '[{"text": "Nein", "correct": true, "because": "Nützlich, aber nicht immer nötig"}, {"text": "Ja", "correct": false, "because": "Projektabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Kollaborationstool wie Git?', 3, '[{"text": "Code-Zusammenführung", "correct": true, "because": "Ermöglicht paralleles Arbeiten"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Tool-Ziel"}, {"text": "Bessere Grafiken", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Teamarbeit in IT-Projekten erfolgreich?', 5, '[{"text": "Klare Kommunikation", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Gemeinsame Tools", "correct": true, "because": "Synchronisiert Arbeit"}, {"text": "Schnellere CPUs", "correct": false, "because": "Kein Teamfaktor"}, {"text": "Bunte Interfaces", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Slack fördert Teamkommunikation. b) Es ersetzt Versionskontrolle. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Slack ist kein Git-Ersatz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Zusammenarbeit in einem IT-Projekt?', 4, '[{"text": "Aufgabenverteilung", "correct": false, "because": "Klare Rollen nötig"}, {"text": "Dokumentation", "correct": false, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Kollaborationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein zentrales Tool für alle Teams immer besser?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibilität kann nützlich sein"}, {"text": "Ja", "correct": false, "because": "Abhängig von Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Plattform wie Jira für IT-Teams?', 4, '[{"text": "Aufgabenverfolgung", "correct": true, "because": "Sichert Überblick"}, {"text": "Fortschrittskontrolle", "correct": true, "because": "Zeigt Projektstatus"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Tool-Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Kollaboration immer mehr Zeit kostet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Richtige Tools sparen Zeit"}, {"text": "Ja", "correct": false, "because": "Effizienz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die Kommunikation in einem verteilten IT-Team zu verbessern?', 3, '[{"text": "Chat-Tool", "correct": true, "because": "Ermöglicht schnellen Austausch"}, {"text": "Neue Monitore", "correct": false, "because": "Nicht kommunikationsrelevant"}, {"text": "Bunte Designs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gemeinsame Tools reduzieren Fehler. b) Sie machen Meetings überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Meetings oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördern die Zusammenarbeit in einem IT-Projekt?', 5, '[{"text": "Regelmäßiges Feedback", "correct": true, "because": "Verbessert Koordination"}, {"text": "Transparente Ziele", "correct": true, "because": "Gibt Orientierung"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Nur technisch relevant"}, {"text": "Bürogestaltung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Tool für die Teamarbeit einrichte?', 3, '[{"text": "Kompatibilität", "correct": false, "because": "Sichert Integration"}, {"text": "Zugriffskontrolle", "correct": false, "because": "Schützt Daten"}, {"text": "Toolfarbe", "correct": true, "because": "Kein funktionaler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt ein Kollaborationstool persönliche Absprachen?', 3, '[{"text": "Nein", "correct": true, "because": "Persönlicher Austausch bleibt wichtig"}, {"text": "Ja", "correct": false, "because": "Tools ergänzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob verteilte Teams ohne Tools effektiv arbeiten können?', 2, '[{"text": "Nein", "correct": true, "because": "Tools vereinfachen Koordination"}, {"text": "Ja", "correct": false, "because": "Koordination schwieriger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich ein Tool für ein Softwareprojekt einrichte?', 4, '[{"text": "Integration mit Codebasis", "correct": true, "because": "Sichert Zusammenarbeit"}, {"text": "Schnellere Server", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Oberfläche", "correct": false, "because": "Irrelevant"}]');
